#!/bin/sh
# Writes ask.rb, the Homebrew formula that installs a release's binary, from the release's
# checksums.txt. The release workflow runs it after publishing; ask's repository is its own tap:
#
#   brew tap arocomputer/ask https://github.com/arocomputer/ask && brew install ask
#
# usage: .github/release/formula.sh vX.Y.Z CHECKSUMS > ask.rb
set -eu
LC_ALL=C
export LC_ALL

if [ "$#" -ne 2 ]; then
  echo 'usage: .github/release/formula.sh vX.Y.Z CHECKSUMS' >&2
  exit 1
fi
tag=$1
sums=$2
case $tag in
  *[!v0-9.rc-]* | '') echo 'formula.sh: invalid release tag' >&2; exit 1 ;;
esac
printf '%s\n' "$tag" | grep -Eq '^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-rc\.[1-9][0-9]*)?$' || {
  echo 'formula.sh: expected vX.Y.Z or vX.Y.Z-rc.N without leading zeros' >&2
  exit 1
}
if [ ! -f "$sums" ] || [ ! -r "$sums" ]; then
  echo 'formula.sh: checksums must be a readable file' >&2
  exit 1
fi

# Require one exact archive filename with a 64-character hexadecimal SHA256.
sha() {
  awk -v file="ask_${tag}_$1.tar.gz" '
    $2 == file {
      count++
      if (NF != 2 || length($1) != 64 || $1 ~ /[^0-9a-fA-F]/) bad = 1
      digest = $1
    }
    END { if (count != 1 || bad) exit 1; print digest }
  ' < "$sums" || {
    echo "formula.sh: invalid or duplicate checksum for $1" >&2
    return 1
  }
}

# Resolve all checksums before writing so invalid input never leaves a partial formula.
darwin_arm64=$(sha darwin_arm64)
darwin_amd64=$(sha darwin_amd64)
linux_arm64=$(sha linux_arm64)
linux_amd64=$(sha linux_amd64)

url() { echo "https://github.com/arocomputer/ask/releases/download/$tag/ask_${tag}_$1.tar.gz"; }
cat <<RUBY
# frozen_string_literal: true

# Generated by .github/release/formula.sh for each release; edit that script, not this file.
class Ask < Formula
  desc "Hand tasks to subagents that work in the background"
  homepage "https://github.com/arocomputer/ask"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "$(url darwin_arm64)"
      sha256 "$darwin_arm64"
    end
    on_intel do
      url "$(url darwin_amd64)"
      sha256 "$darwin_amd64"
    end
  end

  on_linux do
    depends_on "bubblewrap"
    on_arm do
      url "$(url linux_arm64)"
      sha256 "$linux_arm64"
    end
    on_intel do
      url "$(url linux_amd64)"
      sha256 "$linux_amd64"
    end
  end

  def install
    bin.install "ask"
    # Landlock/seccomp enforcement inside bubblewrap for commands and filesystem tools.
    bin.install "sandybox" if OS.linux?
  end

  def caveats
    <<~EOS
      Next: ask settings
    EOS
  end

  test do
    assert_equal "ask version #{version}", shell_output("#{bin}/ask --version").strip
  end
end
RUBY
